import {ControlGroup} from '@github-ui/control-group'

import type {TemplateRepo} from '../types/repo-creation-types'
import {TemplateDropdown} from './TemplateDropdown'

const label = 'Repository template'

export function RepoTemplateMenuV2({
  selectedTemplateRepo,
  onRepoTemplateSelect,
  includeAllBranches,
  onIncludeAllBranchesChange,
}: {
  selectedTemplateRepo?: TemplateRepo
  onRepoTemplateSelect: (selectedTemplateRepo?: TemplateRepo) => void
  includeAllBranches: boolean
  onIncludeAllBranchesChange: (includeAllBranches: boolean) => void
}) {
  return (
    <ControlGroup>
      <ControlGroup.Item>
        <ControlGroup.Title className="fgColor-default" as="h2">
          Start with a template
        </ControlGroup.Title>
        <ControlGroup.Description>Templates pre-configure your repository with files.</ControlGroup.Description>
        <ControlGroup.Custom>
          <TemplateDropdown {...{selectedTemplateRepo, onRepoTemplateSelect, label}} />
        </ControlGroup.Custom>
      </ControlGroup.Item>
      {selectedTemplateRepo && (
        <ControlGroup.Item nestedLevel={1}>
          <ControlGroup.Title className="fgColor-default" id="include-all-branches">
            Include all branches
          </ControlGroup.Title>
          <ControlGroup.Description>
            If enabled, all branches from the template repository will be included.
          </ControlGroup.Description>
          <ControlGroup.ToggleSwitch
            aria-labelledby="include-all-branches"
            checked={includeAllBranches}
            onClick={e => {
              e.preventDefault()
              onIncludeAllBranchesChange(!includeAllBranches)
            }}
          />
        </ControlGroup.Item>
      )}
    </ControlGroup>
  )
}

try{ RepoTemplateMenuV2.displayName ||= 'RepoTemplateMenuV2' } catch {}