import {useEffect} from 'react'

const TIME_ON_PAGE_MARK_NAME = 'repo-create-page-start'
const TIME_ON_PAGE_MEASURE_NAME = 'repo-create-additional-time'

export function useUpdateTimeSpentOnPage(timeOnPage: React.MutableRefObject<number>): (forceMeasure: boolean) => void {
  // track time spent on page. initial mark is created in the useEffect below, so time starts when the component renders.
  // when the page loses focus or the form is submitting, take a measurement and add it to the total time.
  function updateTimeSpentOnPage(forceMeasure: boolean) {
    if (document.visibilityState === 'hidden' || forceMeasure) {
      const marks = performance.getEntriesByName(TIME_ON_PAGE_MARK_NAME)

      if (marks.length && timeOnPage.current >= 0) {
        const measure = performance.measure(TIME_ON_PAGE_MEASURE_NAME, TIME_ON_PAGE_MARK_NAME)
        timeOnPage.current += measure?.duration ?? 0
      } else {
        // something bugged out and the mark doesn't exist, likely on safari due to how it handles background tabs.
        // purposely set it to -1, which the controller will filter out and not log
        timeOnPage.current = -1
      }

      performance.clearMarks(TIME_ON_PAGE_MARK_NAME)
      performance.clearMeasures(TIME_ON_PAGE_MEASURE_NAME)
    } else {
      performance.mark(TIME_ON_PAGE_MARK_NAME)
    }
  }

  function visibilityChangeListenerFunction() {
    updateTimeSpentOnPage(false)
  }

  useEffect(() => {
    performance.mark(TIME_ON_PAGE_MARK_NAME)
    window.addEventListener('visibilitychange', visibilityChangeListenerFunction)

    return () => {
      performance.clearMarks(TIME_ON_PAGE_MARK_NAME)
      performance.clearMeasures(TIME_ON_PAGE_MEASURE_NAME)
      window.removeEventListener('visibilitychange', visibilityChangeListenerFunction)
    }

    // empty dependency array so this only runs on initial render
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return updateTimeSpentOnPage
}
